corrected_code:
const deliveryTrackingResolvers = {
  Subscription: {
    courierLocationUpdated: {
      subscribe: withFilter(
        () => pubsub.asyncIterator(['COURIER_GPS_EVENTS']),
        async (payload, args, context) => {
          if (!context.user || payload.trackingNumber !== args.trackingNumber) return false;
          const shipment = await Shipment.findOne({ where: { trackingNumber: args.trackingNumber, recipientId: context.user.id } });
          return !!shipment;
        }
      ),
      resolve: (payload) => payload.coordinates
    }
  }
};
